DROP TABLE IF EXISTS `m_product_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `m_product_type` (
  `product_type_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kode tipe produk. PK.',
  `product_type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama tampil (ID).',
  `category` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PACKAGING' COMMENT 'Kategori (static SC): PACKAGING / COMMERCIAL_PRINT / DISPLAY / MISC.',
  `sub_category` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Sub-kategori: TUCK_BOX, TRAY, CYLINDER, POLYGONAL, FLAT_PRINT, dll.',
  `box_style` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'REVERSE_TUCK, STRAIGHT_TUCK, SLEEVE, AUTO_LOCK…',
  `photo_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Foto preview 3D (ref. Templatemaker). Contoh: /img/producttype/CARD_BOX.jpg',
  `svg_generator` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kunci generator SVG dieline (mis. TUCK_END, SLEEVE, PILLOW). NULL = belum ada preview dinamis.',
  `dieline_sample` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'File SVG statis fallback bila svg_generator NULL.',
  `ecma_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode ECMA default.',
  `part_type_default` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Default m_part_type.part_type_code.',
  `has_multi_part` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '1 = umumnya >1 part (Body+Lid, dsb).',
  `sort_order` smallint unsigned NOT NULL DEFAULT '999' COMMENT 'Urutan tampil di galeri.',
  `activate` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '1=aktif.',
  `notes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Keterangan.',
  `create_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `dieline_spec` json DEFAULT NULL COMMENT 'DSL deklaratif dieline (vars/elements/flat)',
  `material_filter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Filter opsional dropdown material (mis. category1=KERTAS). NULL = semua MATERIAL.',
  `spec_version` smallint NOT NULL DEFAULT '1',
  PRIMARY KEY (`product_type_code`) USING BTREE,
  KEY `idx_m_ptype_cat` (`category`,`sort_order`) USING BTREE,
  KEY `idx_m_ptype_active` (`activate`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Master tipe produk (galeri thumbnail). Menentukan kolom dimensi mana yang tampil.';
